package com.cursortickring;

import net.runelite.client.RuneLite;
import net.runelite.client.externalplugins.ExternalPluginManager;

public class CursorTickPluginTest
{
	public static void main(String[] args) throws Exception
	{
		ExternalPluginManager.loadBuiltin(CursorTickPlugin.class);
		RuneLite.main(args);
	}
}

package com.cursortickring;

import org.junit.Test;

import static org.junit.Assert.assertEquals;

public class TickCycleTest
{
	@Test
	public void startsAtOneAndRepeats()
	{
		TickCycle cycle = new TickCycle();

		assertEquals(0, cycle.positionAt(0L, 4));
		assertEquals(1, cycle.positionAt(1L, 4));
		assertEquals(4, cycle.positionAt(4L, 4));
		assertEquals(1, cycle.positionAt(5L, 4));
	}

	@Test
	public void restartMakesTheCurrentTickPositionOne()
	{
		TickCycle cycle = new TickCycle();
		cycle.restartAt(11L);

		assertEquals(1, cycle.positionAt(11L, 4));
		assertEquals(2, cycle.positionAt(12L, 4));
		assertEquals(1, cycle.positionAt(15L, 4));
	}

	@Test
	public void resetRestoresTheOriginalCycleOrigin()
	{
		TickCycle cycle = new TickCycle();
		cycle.restartAt(7L);
		cycle.reset();

		assertEquals(3, cycle.positionAt(7L, 4));
	}
}

package com.cursortickring;

import java.awt.Color;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class CursorTickConfigTest
{
	private final CursorTickConfig config = new CursorTickConfig()
	{
	};

	@Test
	public void usesRequestedGeneralDefaults()
	{
		assertEquals(VisibilityMode.LOGGED_IN, config.visibilityMode());
		assertFalse(config.gameViewportOnly());
		assertTrue(config.hideWhenMenuOpen());
		assertEquals(10, config.idleFadeDelaySeconds());
		assertEquals(1, config.idleFadeDurationSeconds());
		assertTrue(config.antiAliasing());
		assertTrue(config.showFeedbackOutline());
	}

	@Test
	public void usesRequestedTimingAndLabelDefaults()
	{
		assertEquals(TimingMode.FIXED, config.timingMode());
		assertEquals(600, config.tickDuration());
		assertEquals(20, config.adaptationStrength());
		assertEquals(0, config.phaseOffset());
		assertFalse(config.pulseOnTick());
		assertEquals(1, config.pulseCycleTick());
		assertEquals(110, config.pulseOnTickDuration());
		assertEquals(4, config.pulseOnTickExpansion());
		assertEquals(new Color(255, 255, 255, 210), config.pulseOnTickColor());
		assertTrue(config.showTickLabel());
		assertEquals(4, config.cycleLength());
		assertTrue(config.cycleStartAccent());
	}

	@Test
	public void usesRequestedClickAndCursorDefaults()
	{
		assertTrue(config.showClickPulse());
		assertEquals(ClickAnchor.CLICK_LOCATION, config.clickAnchor());
		assertEquals(260, config.clickPulseDuration());
		assertEquals(6, config.clickPulseExpansion());
		assertEquals(2, config.clickPulseThickness());
		assertEquals(new Color(80, 190, 255, 230), config.leftClickColor());
		assertEquals(new Color(255, 95, 120, 230), config.rightClickColor());
		assertEquals(new Color(210, 140, 255, 230), config.middleClickColor());
		assertEquals(CursorMode.SYSTEM, config.cursorMode());
		assertTrue(config.fadeOnTickReset());
		assertEquals(180, config.tickResetFadeDuration());
	}
}

package com.cursortickring;

import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class TickClockTest
{
	private static final long MILLISECOND = 1_000_000L;

	@Test
	public void fixedClockIsResetByGameTicks()
	{
		TickClock clock = new TickClock();
		clock.reset(600);
		assertFalse(clock.getState().isStarted());

		long firstTick = 1_000L * MILLISECOND;
		clock.onGameTick(firstTick, 600, TimingMode.FIXED, 20);

		TickClock.State first = clock.getState();
		assertTrue(first.isStarted());
		assertEquals(1L, first.getTickNumber());
		assertEquals(0.0, first.progressAt(firstTick, 0), 0.0001);
		assertEquals(0.5, first.progressAt(firstTick + 300L * MILLISECOND, 0), 0.0001);
		assertEquals(1.0, first.progressAt(firstTick + 900L * MILLISECOND, 0), 0.0001);

		long secondTick = firstTick + 700L * MILLISECOND;
		clock.onGameTick(secondTick, 600, TimingMode.FIXED, 20);
		TickClock.State second = clock.getState();
		assertEquals(2L, second.getTickNumber());
		assertEquals(600.0, second.getDurationMillis(), 0.0001);
		assertEquals(0.25, second.progressAt(secondTick + 150L * MILLISECOND, 0), 0.0001);
	}

	@Test
	public void phaseOffsetRunsAheadOrBehindWithoutWrapping()
	{
		TickClock clock = new TickClock();
		long tick = 2_000L * MILLISECOND;
		clock.onGameTick(tick, 600, TimingMode.FIXED, 20);
		TickClock.State state = clock.getState();

		assertEquals(2.0 / 3.0, state.progressAt(tick + 300L * MILLISECOND, 100), 0.0001);
		assertEquals(1.0 / 3.0, state.progressAt(tick + 300L * MILLISECOND, -100), 0.0001);
		assertEquals(0.0, state.progressAt(tick, -200), 0.0001);
		assertEquals(1.0, state.progressAt(tick + 550L * MILLISECOND, 100), 0.0001);
	}

	@Test
	public void adaptiveClockSmoothsValidIntervalsAndRejectsOutliers()
	{
		TickClock clock = new TickClock();
		long firstTick = 5_000L * MILLISECOND;
		clock.onGameTick(firstTick, 600, TimingMode.ADAPTIVE, 50);
		clock.onGameTick(firstTick + 660L * MILLISECOND, 600, TimingMode.ADAPTIVE, 50);

		TickClock.State smoothed = clock.getState();
		assertEquals(630.0, smoothed.getDurationMillis(), 0.0001);

		clock.onGameTick(firstTick + 1_660L * MILLISECOND, 600, TimingMode.ADAPTIVE, 50);
		assertEquals(630.0, clock.getState().getDurationMillis(), 0.0001);
	}

	@Test
	public void resetClearsSynchronizationAndTickCount()
	{
		TickClock clock = new TickClock();
		clock.onGameTick(1_000L, 600, TimingMode.FIXED, 20);
		clock.reset(650);

		TickClock.State reset = clock.getState();
		assertFalse(reset.isStarted());
		assertEquals(0L, reset.getTickNumber());
		assertEquals(650.0, reset.getDurationMillis(), 0.0001);
	}
}

package com.cursortickring;

public enum CursorMode
{
	SYSTEM("System cursor", false),
	DOT("Dot", true),
	CROSSHAIR("Crosshair", true),
	HIDDEN("Hidden", true);

	private final String displayName;
	private final boolean hidesSystemCursor;

	CursorMode(String displayName, boolean hidesSystemCursor)
	{
		this.displayName = displayName;
		this.hidesSystemCursor = hidesSystemCursor;
	}

	boolean hidesSystemCursor()
	{
		return hidesSystemCursor;
	}

	@Override
	public String toString()
	{
		return displayName;
	}
}

